            sGfxData.pDC6 = pDC6Table[pEntry->nDC6Index];
            sGfxData.nFrameNumber = pEntry->nFrameNumber;
            D2gfx::D2GFX::D2GFX_DrawImage(&sGfxData, nPositionX, nScreenWidth, -1, DRAW_LIGHTTRANSPARENT, nullptr);
